[
  {
    "id": 11,
    "name": "Zendesk",
    "category": "Support and Helpdesk",
    "one_line": "All-in-one customer service and support platform with ticketing, help center, and messaging, backed by a mature, broadly documented developer platform.",
    "auth_methods": ["OAuth2", "API key", "Basic"],
    "access": {
      "status": "trial_self_serve",
      "note": "14-day free trial, no credit card required, self-serve registration (zendesk.com/register). API tokens created in Admin Center; OAuth clients via Admin Center or API. Startup program offers free access for qualified startups."
    },
    "api": {
      "documented": true,
      "protocols": ["REST", "HTTPS", "JSON"],
      "breadth": "broad",
      "mcp": "community",
      "note": "Full v2 REST API across Ticketing, Help Center, Guide, Talk, Chat, and Sell. OAuth access tokens (Bearer) recommended; legacy API tokens use Basic auth and are being deprecated in favor of OAuth. No official first-party MCP server published; Zendesk docs cover acting as an MCP client and mention Zendesk can act as an MCP server, and multiple community MCP servers exist."
    },
    "buildability": {
      "verdict": "buildable_today",
      "blocker": null
    },
    "evidence": {
      "auth_url": "https://developer.zendesk.com/documentation/authentication/",
      "access_url": "https://www.zendesk.com/free-trial/",
      "api_url": "https://developer.zendesk.com/api-reference/introduction/security-and-auth/",
      "mcp_url": null
    },
    "confidence": "high",
    "research_notes": "Official developer docs confirm OAuth 2.0 (authorization code + PKCE, global OAuth for public apps) and Basic-auth API tokens; API tokens now deprecated in favor of OAuth per security-and-auth docs. Free trial verified on zendesk.com/free-trial. MCP: no first-party server URL found in vendor docs; community servers (e.g., markusvankempen/zendesk-mcp) exist. API breadth broad."
  },
